function ico(name,fill=false){return `<svg viewBox="0 0 24 24" fill="${fill?'currentColor':'none'}" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.bag}</svg>`;}
function load(){if(window.PedeBootstrap){const b=window.PedeBootstrap;return {version:1,stores:b.stores,products:b.products,orders:[],favorites:b.favorites,cart:{storeId:null,items:[]},nextOrder:1,adminStore:b.managedStores[0]||'cantinho'};}return C.seed();}
let state=load(),storageOk=true,view='',shopId='',filter='Todos',search='',orderFilter='all',draft=[],draftWarnings=[],rawText='',importBusy=false,importSource='',pdfReady=null;
let productModal=null,modalQty=1,modalExtras=[],checkoutMode='delivery',checkoutPayment='cash',modalPrevFocus=null;
function save(){/* Persistence is installed by connected.js. */}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
const findShop=id=>state.stores.find(s=>s.id===id),adminShop=()=>findShop(state.adminStore)||state.stores[0];
const isAdmin=()=>['painel','cardapio','importar','areas','configuracoes','piloto'].includes(view);
function navLink(route,label,icon,active){return `<a class="nav-link ${active?'active':''}" href="#/${route}" ${active?'aria-current="page"':''}>${ico(icon)}${label}</a>`;}
function logo(cls=''){return `<a href="#/minhas-lojas" aria-label="Bocali - in\u00edcio" class="logo ${cls}"><span class="mark">${ico('bag')}</span><span>bocali<i>.</i></span></a>`;}
function shell(content){
 const headings={'minhas-lojas':'Minhas lojas',explorar:'Descobrir lojas',loja:'Card\u00e1pio da loja',pedidos:'Meus pedidos',painel:'Painel do estabelecimento',cardapio:'Seu card\u00e1pio',importar:'Importar card\u00e1pio',areas:'Mapa e taxas de entrega',configuracoes:'Configura\u00e7\u00f5es do teste'};
 const navAdmin=[['painel','Painel','grid'],['cardapio','Card\u00e1pio','menu'],['areas','Entregas','location'],['minhas-lojas','Cliente','heart']];
 const navClient=[['minhas-lojas','Minhas lojas','heart'],['explorar','Explorar','compass'],['pedidos','Pedidos','order'],['painel','Minha loja','shop']];
 $('#app').innerHTML=`<aside class="sidebar">${logo()}<p class="brand-caption">seus sabores, por perto.</p><nav aria-label="Menu principal"><div class="nav-label">PARA VOC\u00ca</div>${navLink('minhas-lojas','Minhas lojas','heart',view==='minhas-lojas')}${navLink('explorar','Explorar','compass',view==='explorar')}${navLink('pedidos','Meus pedidos','order',view==='pedidos')}<div class="nav-label">SOU LOJISTA</div>${navLink('painel','Painel da loja','grid',view==='painel')}${navLink('cardapio','Card\u00e1pio','menu',view==='cardapio')}${navLink('importar','Importar PDF','upload',view==='importar')}${navLink('areas','Mapa e taxas','location',view==='areas')}${navLink('piloto','Preparar teste','shield',view==='piloto')}${navLink('configuracoes','Configura\u00e7\u00f5es','settings',view==='configuracoes')}</nav><div class="sidebar-note">${ico('shield')}<strong>Ambiente de demonstra\u00e7\u00e3o</strong>Compras simuladas. Seus testes ficam apenas neste navegador.</div></aside><div class="layout"><header class="topbar">${logo('mobile-brand')}<div class="topbar-title">${ico(isAdmin()?'shop':'location')}${headings[view]||'Bocali'}</div><div class="topbar-right"><span class="demo-tag">BETA 0.8</span><a href="#/${isAdmin()?'loja/'+adminShop().id:'painel'}" class="text-link desktop-link">${isAdmin()?'Ver minha loja':'\u00c1rea do lojista'} ${ico('arrow')}</a><a class="avatar" href="#/configuracoes" aria-label="Op\u00e7\u00f5es da demonstra\u00e7\u00e3o" title="Op\u00e7\u00f5es do teste">D</a></div></header><main id="main" class="main">${content}<footer class="page-footer"><span>Bocali \u00b7 beta 0.8 \u00b7 2026</span><span>Sem cobran\u00e7as. Sem pedidos reais. Sem conta online.</span></footer></main></div><nav class="bottomnav" aria-label="Navega\u00e7\u00e3o m\u00f3vel">${(isAdmin()?navAdmin:navClient).map(([r,l,i])=>`<a href="#/${r}" class="${view===r?'active':''}" ${view===r?'aria-current="page"':''}>${ico(i)}${l}</a>`).join('')}</nav>${view==='loja'&&state.cart.items.length?`<button class="btn cart-mobile" data-action="cart">${ico('bag')} <span>Ver sacola \u00b7 ${C.totals(state.cart).quantity} itens</span><strong>${brl(C.totals(state.cart).subtotal)}</strong></button>`:''}`;
}
function storeCard(s){return `<article class="store-card"><button class="icon-btn favorite-on-card ${state.favorites.includes(s.id)?'saved':''}" data-action="favorite" data-id="${s.id}" aria-label="${state.favorites.includes(s.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(s.name)}" aria-pressed="${state.favorites.includes(s.id)}">${ico('heart',state.favorites.includes(s.id))}</button><a href="#/loja/${s.id}" aria-label="Abrir ${esc(s.name)}"><div class="store-cover ${s.tone}"><div class="shop-emblem">${esc(s.initials)}</div></div><div class="store-info"><h3>${esc(s.name)}</h3><p class="muted small">${esc(s.type)} \u00b7 <span class="open-label ${s.open?'':'closed-label'}">${s.open?'Loja aberta':'Pausada'}</span></p><div class="store-meta"><span>${ico('clock')} ${esc(s.eta)}</span><span>Entrega por endere\u00e7o</span></div><p style="font-size:9px;color:#909486;margin-top:8px">${s.id==='cantinho'?'Card\u00e1pio de exemplo, n\u00e3o oficial':'Loja fict\u00edcia de demonstra\u00e7\u00e3o'}</p></div></a></article>`;}
function empty(title,text,link='',label=''){return `<div class="empty empty-wide"><div class="empty-icon">${ico('bag')}</div><strong>${title}</strong><p>${text}</p>${link?`<a class="btn secondary" href="${link}">${label}</a>`:''}</div>`;}
function favoritesView(){
 const favorite=state.stores.filter(s=>state.favorites.includes(s.id));const visited=state.stores.filter(s=>state.orders.some(o=>o.storeId===s.id));
 return `<section class="hero"><div><div class="eyebrow">SUA PR\u00d3XIMA ESCOLHA EST\u00c1 AQUI</div><h1>Seus favoritos,<br>sempre por perto.</h1><p>Os lugares que voc\u00ea gosta. Os sabores que d\u00e1 vontade de repetir. Tudo no mesmo lugar.</p><div class="hero-footer" aria-hidden="true"><span class="dot active"></span><span class="dot"></span><span class="dot"></span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="float-icon one">${ico('heart',true)}</div><div class="art-bag"><span>bocali.</span><small>BONS PEDIDOS</small></div><div class="float-icon two">${ico('pastel')}</div></div></section><div class="section-heading"><h2>Minhas favoritas <span>${favorite.length}</span></h2><a class="text-link" href="#/explorar">Ver outras lojas ${ico('arrow')}</a></div>${favorite.length?`<div class="store-grid">${favorite.map(storeCard).join('')}</div>`:empty('Sua lista, do seu jeito','Toque no cora\u00e7\u00e3o de uma loja para salv\u00e1-la.','#/explorar','Encontrar uma loja')}<div class="hint-bar">${ico('heart')}<div><strong>O link que voc\u00ea n\u00e3o precisa mais procurar.</strong><p>Salve suas lojas e volte para pedir em poucos toques.</p></div><a class="text-link" href="#/explorar">Explorar ${ico('arrow')}</a></div><div class="section-heading"><h2>J\u00e1 pedi aqui</h2><a class="text-link" href="#/pedidos">Meu hist\u00f3rico ${ico('arrow')}</a></div>${visited.length?`<div class="store-grid">${visited.map(storeCard).join('')}</div>`:`<div class="panel row">${ico('order')}<div><strong class="small">Seu primeiro pedido come\u00e7a aqui.</strong><p class="small muted">Depois de simular uma compra, a loja aparece nesta se\u00e7\u00e3o.</p></div></div>`}<p class="small muted spaced">As favoritas iniciais s\u00e3o exemplos. Produtos, pre\u00e7os, prazos e entregas s\u00e3o ilustrativos.</p>`;
}
function exploreView(){return `<div class="page-heading"><div><div class="eyebrow muted" style="margin-bottom:10px">SEU PR\u00d3XIMO FAVORITO</div><h1>O que vai bem hoje?</h1><p>Explore as lojas de demonstra\u00e7\u00e3o e salve as que gostar.</p></div></div><div class="toolbar"><label class="search"><span class="only-screen-reader">Buscar lojas</span>${ico('search')}<input id="store-search" placeholder="Busque uma loja ou um tipo de comida" value="${esc(search)}"></label></div><div id="explore-results" class="store-grid">${state.stores.filter(s=>C.norm(s.name+' '+s.type).includes(C.norm(search))).map(storeCard).join('')}</div><div class="hint-bar">${ico('shop')}<div><strong>Cada loja tem seu pr\u00f3prio espa\u00e7o.</strong><p>Ao entrar por um link direto, o cliente v\u00ea s\u00f3 aquela loja. Nenhuma propaganda de concorrente no card\u00e1pio.</p></div></div>`;}
function productCard(p){return `<button class="product" data-action="product" data-id="${p.id}" ${!p.available?'disabled':''}><div class="product-info"><h3>${esc(p.name)}</h3><p>${esc(p.description||'Produto importado. Confira as informa\u00e7\u00f5es com o estabelecimento.')}</p><strong>${brl(p.price)}</strong></div><div class="product-art ${esc(p.art)}" aria-hidden="true">${ico(p.art)}<span class="product-add">${ico('plus')}</span></div></button>`;}
function storeView(){const s=findShop(shopId);if(!s)return empty('Loja n\u00e3o encontrada','Escolha uma das lojas cadastradas.','#/minhas-lojas','Voltar');
 const products=state.products.filter(p=>p.storeId===s.id&&p.available);const categories=['Todos',...new Set(products.map(p=>p.category))];
 return `<a href="#/minhas-lojas" class="text-link" style="margin-bottom:18px">${ico('back')} Minhas lojas</a><section class="store-banner ${s.tone}"><div class="shop-emblem">${esc(s.initials)}</div><div><div class="eyebrow">${esc(s.tag)}</div><h1>${esc(s.name)}</h1><p>${esc(s.description)}</p></div><button class="icon-btn ${state.favorites.includes(s.id)?'saved':''}" data-action="favorite" data-id="${s.id}" aria-label="Salvar ou remover loja dos favoritos">${ico('heart',state.favorites.includes(s.id))}</button></section><div class="detail-tags"><span class="open-label ${s.open?'':'closed-label'}">${s.open?'Aberta na demonstra\u00e7\u00e3o':'Pedidos pausados'}</span><span>${ico('clock')} ${esc(s.eta)}</span><span>${ico('bag')} M\u00ednimo ${brl(s.minimum)}</span><span>${ico('location')} Entrega por endere\u00e7o</span><button class="text-link" data-action="share" data-id="${s.id}">${ico('link')} Link da loja</button></div><div class="notice">Card\u00e1pio de demonstra\u00e7\u00e3o: produtos, ingredientes, pre\u00e7os e condi\u00e7\u00f5es n\u00e3o s\u00e3o os dados oficiais do estabelecimento. Nenhum pedido ser\u00e1 enviado.</div>${!s.open?'<div class="notice red spaced">Esta loja est\u00e1 pausada no teste. Reabra pelo painel antes de simular uma compra.</div>':''}<div class="toolbar"><label class="search"><span class="only-screen-reader">Buscar no card\u00e1pio</span>${ico('search')}<input id="menu-search" placeholder="Qual sabor voc\u00ea est\u00e1 procurando?" value="${esc(search)}"></label></div><div class="chips" style="margin-bottom:22px">${categories.map(c=>`<button class="chip ${filter===c?'active':''}" data-action="category" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="menu-layout"><div><div id="product-results" class="product-grid">${products.filter(p=>(filter==='Todos'||p.category===filter)&&C.norm(p.name+' '+p.description).includes(C.norm(search))).map(productCard).join('')||'<p class="muted">Nenhum produto encontrado.</p>'}</div><p class="small muted spaced">Ilustra\u00e7\u00f5es indicativas. As fotos reais ser\u00e3o adicionadas pelo estabelecimento.</p></div><aside class="cart-panel" aria-label="Sacola">${cartHTML()}</aside></div>`;
}
function cartHTML(){const t=C.totals(state.cart);const s=findShop(state.cart.storeId);return `<h3>${ico('bag')} Sua sacola ${t.quantity?`<span class="muted small">(${t.quantity})</span>`:''}</h3>${!state.cart.items.length?`<div class="empty"><div class="empty-icon">${ico('bag')}</div><strong>Uma del\u00edcia por vez.</strong>Escolha um produto para come\u00e7ar seu pedido.</div>`:`<p class="small muted">${esc(s?.name||'')}</p>${state.cart.items.map((i,index)=>`<div class="cart-line"><div class="line-content"><strong>${esc(i.name)}</strong>${i.extras.length?`<small>${i.extras.map(e=>esc(e.name)).join(', ')}</small><br>`:''}${i.note?`<small>${esc(i.note)}</small>`:''}<div class="qty-small"><button data-action="cart-minus" data-index="${index}" aria-label="Diminuir ${esc(i.name)}">${ico('minus')}</button><span>${i.quantity}</span><button data-action="cart-plus" data-index="${index}" aria-label="Aumentar ${esc(i.name)}">${ico('plus')}</button></div></div><span class="price">${brl((i.unitPrice+i.extras.reduce((s,e)=>s+e.price,0))*i.quantity)}</span></div>`).join('')}<div class="amount-row total"><span>Subtotal</span><span>${brl(t.subtotal)}</span></div><p class="small muted" style="margin-bottom:17px">Entrega calculada na pr\u00f3xima etapa.</p><button class="btn full" data-action="checkout">Continuar ${ico('arrow')}</button><p class="cart-caption">O total final e a taxa de entrega serão confirmados no servidor.</p>`}`;}
const statusLabel={awaiting_payment:'Aguardando pagamento',new:'Aguardando aceite',accepted:'Aceito',preparing:'Em preparo',ready:'Pronto',dispatched:'Saiu para entrega',completed:'Concluído',cancelled:'Cancelado'};
function orderNext(o){return ({accepted:['preparing','Iniciar preparo'],preparing:['ready',o.fulfillment==='pickup'?'Pronto para retirar':'Pronto para sair'],ready:o.fulfillment==='delivery'?['dispatched','Saiu para entrega']:['completed','Confirmar retirada'],dispatched:['completed','Confirmar entrega']})[o.status];}
function orderEta(o){
 if(o.status==='awaiting_payment')return '<div class="eta-info awaiting">'+ico('clock')+'<div><strong>Aguardando confirmação do pagamento</strong><span>O pedido só chega para aceite da loja depois da aprovação.</span></div></div>';
 if(o.status==='new')return '<div class="eta-info awaiting">'+ico('clock')+'<div><strong>Prazo ainda não confirmado</strong><span>O restaurante define a previsão ao aceitar.</span></div></div>';
 if(!o.eta||o.status==='cancelled')return '';
 const label=o.fulfillment==='delivery'?'Entrega prevista':'Retirada prevista',active=!['completed','cancelled'].includes(o.status),late=active&&Date.now()>Date.parse(o.eta.to);
 return `<div class="eta-info ${late?'late':''}">${ico('clock')}<div><strong>${label}: ${clock(o.eta.from)} a ${clock(o.eta.to)}</strong><span>${o.eta.minMinutes}\u2013${o.eta.maxMinutes} min a partir do aceite \u00b7 ${dt(o.acceptedAt)}${late?' \u00b7 prazo estimado ultrapassado':''}</span></div></div>`;
}
function printHint(o){
 if(o.status==='new'||o.status==='cancelled')return '';
 const s=O.printState(o),text={not_requested:'Comanda da cozinha ainda n\u00e3o solicitada',pending:'Confira se a comanda saiu na impressora',failed:'Impress\u00e3o n\u00e3o saiu: tente novamente',confirmed:'Comanda confirmada pelo operador'}[s];
 return `<div class="print-hint ${s==='confirmed'?'ok':'warn'}">${ico('printer')}<span>${text}</span></div>`;
}
function orderCard(o,admin=false){
 const steps=[...(o.status==='awaiting_payment'?['awaiting_payment']:[]),'new','accepted','preparing','ready',...(o.fulfillment==='delivery'?['dispatched']:[]),'completed'];
 const step=steps.indexOf(o.status),next=orderNext(o);
 let actions='';
 if(admin){
  if(o.status==='new')actions+=`<button class="btn" data-action="accept-order" data-id="${esc(o.id)}">${ico('check')} Aceitar e definir prazo</button>`;
  if(next)actions+=`<button class="btn" data-action="status" data-id="${esc(o.id)}" data-to="${next[0]}">${next[1]}</button>`;
  if(!['awaiting_payment','completed','cancelled'].includes(o.status))actions+=`<button class="btn danger" data-action="status" data-id="${esc(o.id)}" data-to="cancelled">${o.status==='new'?'Recusar':'Cancelar'}</button>`;
 }else if(o.status==='awaiting_payment'){
  actions=`<button class="btn" data-net="pay-order" data-id="${esc(o.id)}">Pagar agora</button>`;
 }else{
  actions=`<button class="btn secondary" data-action="reorder" data-id="${esc(o.id)}">${ico('bag')} Pedir novamente</button>`;
 }
 const paymentText=o.payment==='cash'?'pagar na entrega/retirada':o.paymentStatus==='approved'?'pago':o.paymentStatus==='rejected'?'pagamento recusado':'aguardando pagamento';
 return `<article class="order-card ${admin&&o.status==='new'?'incoming':''}" data-order-id="${esc(o.id)}"><div class="order-top"><div><h3>${esc(admin?o.id:o.storeName)}</h3><p>${admin?esc(o.customerName||'Cliente'):esc(o.id)} · ${dt(o.createdAt)}</p></div><div class="order-badges"><span class="fulfillment-badge ${o.fulfillment}">${o.fulfillment==='delivery'?'ENTREGA':'RETIRADA / BALCÃO'}</span><span class="status ${o.status}">${statusLabel[o.status]||o.status}</span></div></div>${orderEta(o)}${typeof deliveryOrderHTML==='function'?deliveryOrderHTML(o):''}<div class="order-body">${o.items.map(i=>`<div><span><b>${i.quantity}×</b> ${esc(i.name)}${i.extras.length?' <small class="muted">+ '+i.extras.map(e=>esc(e.name)).join(', ')+'</small>':''}${i.note?'<br><small class="item-note">OBS.: '+esc(i.note)+'</small>':''}</span><span>${brl((i.unitPrice+i.extras.reduce((sum,e)=>sum+e.price,0))*i.quantity)}</span></div>`).join('')}${o.fee?`<div class="muted"><span>Entrega</span><span>${brl(o.fee)}</span></div>`:''}</div>${o.note?`<div class="order-note"><strong>Observação do pedido</strong><p>${esc(o.note)}</p></div>`:''}${admin?printHint(o):''}<div class="order-bottom"><div><strong>${brl(o.total)}</strong><div class="muted" style="font-size:10px">${({cash:'Dinheiro',card:'Cartão',pix:'Pix'})[o.payment]||o.payment} · ${paymentText}</div></div><div class="order-actions">${actions}</div></div>${admin&&O.canPrint(o,'kitchen')?`<div class="print-actions"><button class="btn secondary" data-action="receipt" data-id="${esc(o.id)}" data-kind="kitchen">${ico('printer')} Comanda da cozinha</button><button class="text-link" data-action="receipt" data-id="${esc(o.id)}" data-kind="counter">Via do balcão</button></div>`:''}${admin&&O.canPrint(o,'cancellation')?`<div class="notice red spaced">Cancelamento não recolhe a comanda já impressa. Avise a cozinha.<button class="btn danger spaced" data-action="receipt" data-id="${esc(o.id)}" data-kind="cancellation">Imprimir aviso de cancelamento</button></div>`:''}${!admin&&o.status!=='cancelled'?`<div class="timeline">${steps.map((st,n)=>`<div class="timeline-step ${n<=step?'done':''}">${statusLabel[st]||st}</div>`).join('')}</div>`:''}</article>`;
}
function ordersView(){return `<div class="page-heading"><div><h1>Seus pedidos, acompanhados.</h1><p>Veja pagamento, prazo confirmado pela loja e andamento do pedido.</p></div></div><div class="notice green" style="margin-bottom:22px">O status é sincronizado com o servidor Bocali. Mantenha o aplicativo atualizado para acompanhar alterações.</div>${state.orders.length?state.orders.map(o=>orderCard(o)).join(''):empty('Seu hist\u00f3rico est\u00e1 come\u00e7ando','Escolha uma loja e simule seu primeiro pedido.','#/explorar','Explorar lojas')}`;}

function adminSelect(){return `<label><span class="only-screen-reader">Estabelecimento do painel de demonstra\u00e7\u00e3o</span><select id="admin-select" class="admin-selector">${state.stores.map(s=>`<option value="${s.id}" ${s.id===state.adminStore?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>`;}
function adminHeading(title,subtitle){return `<div class="page-heading"><div><div class="eyebrow muted" style="margin-bottom:10px">\u00c1REA DO LOJISTA \u00b7 TESTE SEM LOGIN</div><h1>${title}</h1><p>${subtitle}</p></div>${adminSelect()}</div>`;}
function dashboardView(){
 const s=adminShop(),all=state.orders.filter(o=>o.storeId===s.id),active=all.filter(o=>!['completed','cancelled'].includes(o.status)),fresh=all.filter(o=>o.status==='new'),pending=active.filter(o=>o.status!=='new'&&O.printState(o)!=='confirmed'),prefs=printerPrefs();
 let shown=orderFilter==='all'?all:orderFilter==='printing'?pending:all.filter(o=>o.status===orderFilter);
 shown=[...shown].sort((a,b)=>(a.status==='new'?0:1)-(b.status==='new'?0:1)||(a.status==='new'&&b.status==='new'?Date.parse(a.createdAt)-Date.parse(b.createdAt):Date.parse(b.createdAt)-Date.parse(a.createdAt)));
 return `${adminHeading('Aceitador de pedidos.','Defina o prazo. Aceite. Envie a comanda para a cozinha.')}${typeof deliverySummaryHTML==='function'?deliverySummaryHTML(s):''}<div class="acceptor-shop"><div class="row"><div class="mini-emblem">${esc(s.initials)}</div><div class="grow"><strong>${esc(s.name)}</strong><p class="small muted">${s.open?'Recebendo pedidos':'Novos pedidos pausados'}</p></div></div><div class="row"><span class="open-label ${s.open?'':'closed-label'}">${s.open?'Loja aberta':'Pausada'}</span><button class="switch ${s.open?'on':''}" role="switch" aria-checked="${s.open}" aria-label="Abrir ou pausar loja" data-action="toggle-store"></button></div></div><div class="stats acceptor-stats"><div class="stat"><div class="stat-head">Aguardando aceite ${ico('bell')}</div><div class="stat-value">${fresh.length}</div><small>Atenda primeiro os mais antigos</small></div><div class="stat"><div class="stat-head">Em andamento ${ico('clock')}</div><div class="stat-value">${active.filter(o=>o.status!=='new').length}</div><small>Aceitos, em preparo ou em entrega</small></div><div class="stat"><div class="stat-head">Conferir impress\u00e3o ${ico('printer')}</div><div class="stat-value">${pending.length}</div><small>Sem confirma\u00e7\u00e3o manual da cozinha</small></div></div><section class="printer-panel"><div class="printer-panel-head"><div class="row">${ico('printer')}<div><h2>Comandas e impress\u00e3o</h2><p>Comandas da loja</p></div></div><button class="text-link" data-action="printer-help">Como conectar a impressora</button></div><div class="printer-options"><label class="paper-choice">Papel da comanda <select id="printer-width" aria-label="Largura do papel"><option value="80" ${prefs.paper===80?'selected':''}>80 mm</option><option value="58" ${prefs.paper===58?'selected':''}>58 mm</option></select></label><label class="check-label"><input type="checkbox" id="auto-print" ${prefs.autoPrint?'checked':''}>Imprimir ao aceitar</label><button class="btn secondary compact" data-action="toggle-sound">${ico('bell')} ${soundEnabled?'Desativar som':'Ativar som'}</button></div><p class="small muted">O navegador n\u00e3o confirma se o papel saiu. Confira cada comanda; som apenas com esta aba ativa. Impress\u00e3o direta ainda n\u00e3o conectada.</p></section><div class="queue-heading"><div><h2>Fila de pedidos</h2><p class="small muted">${fresh.length?'H\u00e1 pedidos aguardando sua confirma\u00e7\u00e3o.':'Seu atendimento, em um s\u00f3 lugar.'}</p></div><div class="test-order-actions"><button class="btn secondary compact" data-action="demo-order" data-mode="delivery">${ico('plus')} Testar entrega</button><button class="btn secondary compact" data-action="demo-order" data-mode="pickup">Testar retirada</button></div></div><div class="chips" style="margin-bottom:18px">${[['all','Todos'],['new','Novos'],['accepted','Aceitos'],['preparing','Em preparo'],['ready','Prontos'],['dispatched','Em entrega'],['printing','Conferir impress\u00e3o'],['completed','Conclu\u00eddos'],['cancelled','Cancelados']].map(([v,l])=>`<button class="chip ${orderFilter===v?'active':''}" data-action="order-filter" data-filter="${v}">${l}${v==='new'&&fresh.length?' ('+fresh.length+')':''}</button>`).join('')}</div>${shown.length?shown.map(o=>orderCard(o,true)).join(''):empty('Nenhum pedido nesta fila','Use os bot\u00f5es de teste acima ou simule uma compra no card\u00e1pio.','#/loja/'+s.id,'Abrir card\u00e1pio')}<div class="notice spaced">Prot\u00f3tipo local: nada \u00e9 enviado ao restaurante. Dados e pagamentos fict\u00edcios. N\u00e3o substitua seu aceitador atual por esta demonstra\u00e7\u00e3o.</div>`;
}

function editorView(){const s=adminShop(),products=state.products.filter(p=>p.storeId===s.id);return `${adminHeading('Seu card\u00e1pio, do seu jeito.','Edite produtos, pre\u00e7os e disponibilidade sem alterar pedidos antigos.')}<div class="toolbar"><a href="#/importar" class="btn">${ico('upload')} Importar PDF</a><button class="btn secondary" data-action="new-product">${ico('plus')} Adicionar produto</button><a class="text-link" href="#/loja/${s.id}" style="margin-left:auto">Ver loja ${ico('arrow')}</a></div><div class="notice" style="margin-bottom:20px">Os dados iniciais s\u00e3o ilustrativos. Alterar o card\u00e1pio aqui afeta somente esta demonstra\u00e7\u00e3o, n\u00e3o o GloriaFood.</div><div class="panel"><div class="section-heading" style="margin:0 0 8px"><h2>Produtos <span>${products.length}</span></h2><span class="small muted">${products.filter(p=>p.available).length} dispon\u00edveis</span></div>${products.map(p=>`<div class="editor-row"><div class="product-art ${p.art}">${ico(p.art)}</div><div class="grow"><h3>${esc(p.name)}</h3><p class="small muted">${esc(p.category)}${!p.available?' \u00b7 Indispon\u00edvel':''}</p></div><strong class="price">${brl(p.price)}</strong><button class="switch ${p.available?'on':''}" role="switch" aria-checked="${p.available}" aria-label="Disponibilidade de ${esc(p.name)}" data-action="toggle-product" data-id="${p.id}"></button><button class="icon-btn" data-action="edit-product" data-id="${p.id}" aria-label="Editar ${esc(p.name)}">${ico('edit')}</button></div>`).join('')||'<p class="muted">Nenhum produto cadastrado.</p>'}</div>`;}
function importView(){return `${adminHeading('Do PDF para o pedido.','Comece com seu card\u00e1pio. Revise cada produto antes de publicar.')}<div class="steps"><div class="step active"><span class="step-number">1</span>Enviar card\u00e1pio</div><span class="step-line"></span><div class="step ${draft.length?'active':''}"><span class="step-number">2</span>Conferir produtos</div><span class="step-line"></span><div class="step"><span class="step-number">3</span>Publicar no cardápio</div></div><div class="upload-grid"><section class="panel"><div class="dropzone"><div class="upload-icon">${ico('upload')}</div><h3>Aquele card\u00e1pio do WhatsApp.</h3><p>Selecione um PDF com texto selecion\u00e1vel. At\u00e9 10 MB e 25 p\u00e1ginas. N\u00e3o precisa enviar fotos dos documentos pessoais.</p><label><span class="only-screen-reader">Escolher card\u00e1pio PDF</span><input type="file" accept="application/pdf,.pdf" id="pdf-file" class="file-input" ${importBusy||pdfReady===false?'disabled':''}></label><p id="pdf-status" aria-live="polite">${importBusy?'Lendo PDF...':pdfReady===true?'Leitura de PDF conectada ao servidor local.':pdfReady===false?'Leitura de PDF: execute o projeto completo. Neste HTML, use o texto colado abaixo.':'Verificando leitor de PDF...'}</p></div><details class="details" ${!draft.length?'open':''}><summary>Colar o texto ou experimentar com um exemplo</summary><p class="small muted">Uma linha por produto. Exemplo: Pastel de queijo R$ 14,90. Sem precisar enviar arquivo.</p><textarea class="raw-text" id="raw-text" aria-label="Texto do card\u00e1pio" placeholder="CL\u00c1SSICOS&#10;Pastel de queijo R$ 14,90&#10;Pastel de carne R$ 15,90">${esc(rawText)}</textarea><div class="row" style="flex-wrap:wrap"><button class="btn secondary" data-action="parse-text">${ico('file')} Organizar produtos</button><button class="text-link" data-action="sample-menu">Usar exemplo</button></div></details></section><aside class="panel"><h2>Voc\u00ea continua no controle.</h2><div class="check-list"><div class="check-row">${ico('check')}<div><strong>Um rascunho, n\u00e3o uma publica\u00e7\u00e3o.</strong><p>A leitura organiza nomes e pre\u00e7os reconhecidos. Voc\u00ea confere tudo.</p></div></div><div class="check-row">${ico('check')}<div><strong>Sem inventar ingredientes ou fotos.</strong><p>Descri\u00e7\u00f5es e adicionais ficam para cadastro manual.</p></div></div><div class="check-row">${ico('check')}<div><strong>Mais de um pre\u00e7o? Precisa revisar.</strong><p>Tamanhos e colunas misturadas n\u00e3o s\u00e3o publicados automaticamente.</p></div></div><div class="check-row">${ico('shield')}<div><strong>Arquivo tempor\u00e1rio, teste local.</strong><p>O servidor inclu\u00eddo l\u00ea o PDF em mem\u00f3ria e n\u00e3o o salva. Sem IA externa.</p></div></div></div></aside></div>${draft.length?`<div class="section-heading"><h2>Confira seu rascunho <span>${draft.length}</span></h2><button class="text-link" data-action="add-draft">${ico('plus')} Nova linha</button></div><div class="notice"><strong>Confira o PDF completo, n\u00e3o apenas as linhas abaixo.</strong> Linhas podem ser omitidas, agrupadas ou lidas incorretamente. ${esc(importSource)}<div class="warning-list">${draftWarnings.map(w=>`<p>${esc(w)}</p>`).join('')}</div></div><div id="draft-list">${draft.map(d=>draftRow(d)).join('')}</div><div class="publish-bar"><div><strong id="review-count">${draft.filter(C.validDraft).length} de ${draft.length} conferidos</strong><small>Adiciona novos produtos. N\u00e3o substitui o card\u00e1pio existente.</small></div><div class="row" style="flex-wrap:wrap;justify-content:flex-end"><button class="btn secondary" data-action="review-clear">${ico('check')} Marcar leituras claras</button><button class="btn" id="publish-button" data-action="publish" ${draft.every(C.validDraft)?'':'disabled'}>${ico('check')} Publicar no cardápio</button></div></div>`:''}`;}
function draftRow(d){
 const level=d.ambiguous?'low':(d.confidence||'medium');
 const labels={high:'Leitura clara',medium:'Conferir',low:'Mais de um preço'};
 const options=Array.isArray(d.priceOptions)&&d.priceOptions.length>1?`<div class="price-options"><strong>Valores encontrados:</strong> ${d.priceOptions.map(v=>brl(v)).join(' · ')}</div>`:'';
 return `<article class="draft confidence-${level}" data-draft="${d.id}"><div class="draft-footer"><strong class="small">Produto para conferência</strong><span class="confidence-badge ${level}">${labels[level]||'Conferir'}</span><button class="icon-btn" data-action="remove-draft" data-id="${d.id}" aria-label="Remover linha do rascunho">${ico('trash')}</button></div><div class="draft-grid"><label>Nome do produto<input data-draft-id="${d.id}" data-field="name" value="${esc(d.name)}" maxlength="100" required></label><label>Categoria<input data-draft-id="${d.id}" data-field="category" value="${esc(d.category)}" maxlength="50" required></label><label>Preço (R$)<input data-draft-id="${d.id}" data-field="price" value="${d.price===null?'':(d.price/100).toFixed(2).replace('.',',')}" placeholder="Confirme o valor" inputmode="decimal" required></label></div><label style="display:block;margin-top:14px">Descrição (opcional)<input data-draft-id="${d.id}" data-field="description" value="${esc(d.description||'')}" maxlength="240" placeholder="Preencha sem inventar informações do produto"></label>${options}<div class="source">Texto original${d.line?' · linha '+d.line:''}: ${esc(d.source||'Cadastro manual')}</div><label class="check-label"><input type="checkbox" data-review="${d.id}" ${d.reviewed?'checked':''}>Conferi nome, categoria e preço no cardápio.</label></article>`;
}
function settingsView(){return `${adminHeading('Um teste com transpar\u00eancia.','Veja o que est\u00e1 funcionando e o que ainda precisa ser conectado.')}<div class="panel"><h2>Sobre esta vers\u00e3o</h2><div class="info-box"><strong>Funciona neste navegador</strong><p>Card\u00e1pios, favoritos, sacola, pedidos simulados, aceite com prazo, comandas via navegador, fila da loja, edi\u00e7\u00e3o de produtos e revis\u00e3o de importa\u00e7\u00e3o. Os testes s\u00e3o salvos no armazenamento local, quando permitido.</p></div><div class="info-box"><strong>Ainda n\u00e3o \u00e9 uma opera\u00e7\u00e3o comercial</strong><p>Sem login real, banco de dados compartilhado, pagamentos, disparos de WhatsApp, impress\u00e3o direta, entregadores ou transmiss\u00e3o de pedidos ao restaurante. O seletor de lojas \u00e9 uma demonstra\u00e7\u00e3o, n\u00e3o controle de acesso.</p></div><div class="info-box"><strong>O que acontece com o PDF?</strong><p>No projeto completo, o arquivo vai para o servidor que voc\u00ea executar, \u00e9 lido em mem\u00f3ria e n\u00e3o \u00e9 mantido em disco. O parser organiza texto por regras, sem IA externa e sem OCR. O rascunho deve ser conferido integralmente.</p></div><div class="info-box"><strong>N\u00e3o use dados de clientes reais</strong><p>Todos que acessam este perfil do navegador podem ver os dados locais. Eles n\u00e3o s\u00e3o sincronizados entre aparelhos. A limpeza do navegador pode apag\u00e1-los.</p></div><div class="toolbar"><button class="btn secondary" data-action="export">${ico('download')} Exportar dados do teste</button><button class="btn danger" data-action="reset">Reiniciar demonstra\u00e7\u00e3o</button></div><div class="notice">${storageOk?'Armazenamento local habilitado.':'Armazenamento local indispon\u00edvel. As mudan\u00e7as durar\u00e3o apenas nesta aba.'} Bocali \u00e9 o nome escolhido para o projeto. Disponibilidade de marca e dom\u00ednio ainda n\u00e3o foi verificada.</div></div>`;}
function render(){if(window.PedeDelivery)window.PedeDelivery.migrate(state);let content;switch(view){case'minhas-lojas':content=favoritesView();break;case'explorar':content=exploreView();break;case'loja':content=storeView();break;case'pedidos':content=ordersView();break;case'painel':content=dashboardView();break;case'cardapio':content=editorView();break;case'importar':content=importView();break;case'areas':content=typeof deliveryView==='function'?deliveryView():'';break;case'configuracoes':content=settingsView();break;default:content=favoritesView();}shell(content);if(view==='areas'&&typeof mountDeliveryMap==='function')mountDeliveryMap();if(view==='importar'&&pdfReady===null)checkPdfServer();}
function route(){const bits=location.hash.replace(/^#\/?/,'').split('/');view=bits[0]||'minhas-lojas';shopId=bits[1]||'cantinho';filter='Todos';search='';closeModal();render();window.scrollTo({top:0});}
function openModal(title,body){modalPrevFocus=document.activeElement;const m=$('#modal');m.className='modal';m.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Fechar janela">${ico('close')}</button></div><div class="modal-content">${body}</div>`;if(!m.open)m.showModal();}
function closeModal(){document.body.classList.remove('receipt-print-active');$('#print-root')?.replaceChildren();const m=$('#modal');if(m.open)m.close();productModal=null;}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('close',()=>{if(modalPrevFocus?.isConnected)modalPrevFocus.focus();});
function showProduct(id){const p=state.products.find(p=>p.id===id);if(!p||!p.available)return;productModal=p;modalQty=1;modalExtras=[];openModal(esc(p.name),`<div class="modal-product">${ico(p.art)}</div><strong>${brl(p.price)}</strong><p class="modal-description">${esc(p.description)}</p>${p.extras.length?`<h3 class="small">Deixe do seu jeito <span class="muted">\u00b7 opcionais</span></h3>${p.extras.map(e=>`<div class="extra"><label><input type="checkbox" data-extra="${e.id}">${esc(e.name)}</label><span>+ ${brl(e.price)}</span></div>`).join('')}`:''}<label class="field" style="margin-top:20px"><span>Alguma observa\u00e7\u00e3o?</span><textarea id="product-note" maxlength="160" placeholder="Ex.: sem azeitona. Use apenas dados de teste."></textarea></label><div class="modal-footer"><div class="counter"><button data-action="product-minus" aria-label="Diminuir quantidade">${ico('minus')}</button><span id="product-quantity">1</span><button data-action="product-plus" aria-label="Aumentar quantidade">${ico('plus')}</button></div><button class="btn" data-action="add-cart">Adicionar <span id="product-price">${brl(p.price)}</span></button></div><p class="cart-caption">Produto de exemplo. N\u00e3o \u00e9 uma compra real.</p>`);productModal=p;}
function productTotal(){if(!productModal)return;$('#product-quantity').textContent=modalQty;$('#product-price').textContent=brl((productModal.price+productModal.extras.filter(e=>modalExtras.includes(e.id)).reduce((s,e)=>s+e.price,0))*modalQty);}
function addToCart(){const p=productModal;if(!p)return;const s=findShop(p.storeId);if(!s.open)return toast('A loja est\u00e1 pausada no teste.');if(state.cart.items.length&&state.cart.storeId!==p.storeId){if(!confirm('A sacola tem produtos de outra loja. Limpar a sacola e come\u00e7ar este pedido?'))return;state.cart={storeId:null,items:[]};}state.cart.storeId=p.storeId;const extras=p.extras.filter(e=>modalExtras.includes(e.id));const note=$('#product-note').value.trim();const existing=state.cart.items.find(i=>i.productId===p.id&&i.note===note&&JSON.stringify(i.extras)===JSON.stringify(extras)&&i.unitPrice===p.price);if(existing){if(existing.quantity+modalQty>20)return toast('Limite de 20 unidades por item no teste.');existing.quantity+=modalQty;}else state.cart.items.push({id:C.uid(),productId:p.id,name:p.name,unitPrice:p.price,quantity:modalQty,extras:JSON.parse(JSON.stringify(extras)),note});save();closeModal();render();toast('Adicionado \u00e0 sacola de '+s.name+'.');}
function cartModal(){openModal('Sua sacola',cartHTML().replace(/^<h3>[\s\S]*?<\/h3>/,''));}
function reorder(id){const o=state.orders.find(o=>o.id===id);if(!o)return;const s=findShop(o.storeId);if(!s?.open)return toast('Esta loja est\u00e1 pausada.');if(state.cart.items.length&&!confirm('Substituir a sacola pelo pedido anterior, usando pre\u00e7os e disponibilidade atuais?'))return;const items=[];let skipped=0;for(const i of o.items){const p=state.products.find(p=>p.id===i.productId&&p.storeId===o.storeId&&p.available);if(!p){skipped++;continue;}const extras=p.extras.filter(e=>i.extras.some(old=>old.id===e.id));items.push({...i,id:C.uid(),name:p.name,unitPrice:p.price,extras});}if(!items.length)return toast('Nenhum item deste pedido est\u00e1 dispon\u00edvel agora.');state.cart={storeId:o.storeId,items};save();location.hash='#/loja/'+o.storeId;render();toast('Sacola refeita com pre\u00e7os atuais. Confira itens e adicionais.'+(skipped?' '+skipped+' indispon\u00edvel(is) removido(s).':''));}
function editProduct(id){const p=id?state.products.find(p=>p.id===id):null;openModal(p?'Editar produto':'Novo produto',`<form id="product-form" data-id="${p?.id||''}"><label class="field"><span>Nome do produto</span><input name="name" maxlength="100" value="${esc(p?.name||'')}" required></label><div class="field-grid"><label class="field"><span>Categoria</span><input name="category" maxlength="50" value="${esc(p?.category||'Cl\u00e1ssicos')}" required></label><label class="field"><span>Pre\u00e7o (R$)</span><input name="price" inputmode="decimal" value="${p?(p.price/100).toFixed(2).replace('.',','):''}" placeholder="14,90" required></label></div><label class="field"><span>Descri\u00e7\u00e3o (opcional)</span><textarea name="description" maxlength="240">${esc(p?.description||'')}</textarea></label><label class="field"><span>Ilustra\u00e7\u00e3o de exemplo</span><select name="art">${[['pastel','Pastel'],['sweet','Doce'],['drink','Bebida'],['pizza','Pizza'],['acai','A\u00e7a\u00ed']].map(([v,l])=>`<option value="${v}" ${p?.art===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="notice">As altera\u00e7\u00f5es n\u00e3o afetam pedidos anteriores. Confirme ingredientes e informa\u00e7\u00f5es antes de uso comercial.</div><button class="btn full spaced" type="submit">${ico('check')} Salvar no teste</button></form>`);}
function parseText(){rawText=$('#raw-text')?.value||rawText;if(!rawText.trim())return toast('Cole o texto do card\u00e1pio primeiro.');if(rawText.length>200000)return toast('Texto muito grande. Limite: 200 mil caracteres.');if(draft.length&&!confirm('Substituir o rascunho atual? O card\u00e1pio publicado n\u00e3o ser\u00e1 alterado.'))return;const result=C.parseMenu(rawText);draft=result.items;draftWarnings=result.warnings;if(draft.length>250){draft=draft.slice(0,250);draftWarnings.push('Limite de 250 produtos por lote. Confira os itens restantes no texto.');}render();if(!draft.length)toast(result.warnings[0]);else{toast(draft.length+' produtos no rascunho. Confira antes de publicar.');setTimeout(()=>$('#draft-list')?.scrollIntoView({behavior:'smooth',block:'start'}),60);}}
async function checkPdfServer(){if(location.protocol==='file:'){pdfReady=false;}else{try{const r=await fetch('/api/health',{signal:AbortSignal.timeout(2500)});const d=await r.json();pdfReady=!!d.pdf;}catch{pdfReady=false;}}const input=$('#pdf-file');if(input)input.disabled=!pdfReady||importBusy;const el=$('#pdf-status');if(el)el.textContent=pdfReady?'Leitura de PDF conectada ao servidor local.':'Para ler PDF, execute o projeto completo. Neste HTML, cole o texto ou use o exemplo.';}
async function importPdf(file){
 if(!file)return;
 const importStoreId=state.adminStore;
 if(!/\.pdf$/i.test(file.name))return toast('Escolha um arquivo PDF.');
 if(file.size>10*1024*1024)return toast('O limite por arquivo é de 10 MB.');
 if(!pdfReady){toast('O leitor de PDF precisa do servidor do Bocali em execução.');return;}
 if(draft.length&&!confirm('Substituir o rascunho atual por este PDF?'))return;
 importBusy=true;
 const status=$('#pdf-status');if(status)status.textContent='Lendo o PDF e montando o rascunho. Nada será publicado automaticamente.';
 try{
  const data=await file.arrayBuffer();
  const resp=await fetch('/api/import-pdf',{method:'POST',headers:{'Content-Type':'application/pdf'},body:data,signal:AbortSignal.timeout(30000)});
  const result=await resp.json();
  if(state.adminStore!==importStoreId)throw new Error('A loja mudou durante a leitura. Importe novamente na loja correta.');
  if(!resp.ok)throw new Error(result.error||'Não foi possível ler o PDF.');
  rawText=result.text||'';
  const fallback=C.parseMenu(rawText);
  const sourceItems=Array.isArray(result.items)&&result.items.length?result.items:fallback.items;
  draft=sourceItems.slice(0,250).map(x=>({id:x.id||C.uid(),name:String(x.name||''),description:String(x.description||''),category:String(x.category||'Importados'),price:Number.isInteger(x.price)?x.price:null,source:String(x.source||''),reviewed:false,selected:true,ambiguous:!!x.ambiguous,confidence:x.confidence||'medium',priceOptions:Array.isArray(x.priceOptions)?x.priceOptions:[],line:x.line||null}));
  draftWarnings=[...(result.warnings||[])];
  if(!result.items?.length)draftWarnings.push(...fallback.warnings);
  if(sourceItems.length>250)draftWarnings.unshift('Somente os primeiros 250 produtos foram organizados. Divida o cardápio em mais de uma importação.');
  const summary=result.summary||{};
  if(draft.length)draftWarnings.unshift(`Bocali encontrou ${draft.length} produto(s). ${summary.highConfidence||0} leitura(s) clara(s) e ${summary.ambiguous||0} linha(s) com vários preços.`);
  importSource=file.name+' · '+result.pages+' página(s) · leitor '+(result.parserVersion||'local');
  if(!draft.length)toast('PDF lido, mas nenhum produto foi reconhecido. Confira o texto extraído.');
  else toast(draft.length+' produtos montados. Agora confira antes de publicar.');
 }catch(e){toast(e.name==='TimeoutError'?'A leitura excedeu o tempo. Tente um arquivo menor.':e.message);}
 finally{importBusy=false;render();}
}
function updateDraftProgress(){const n=draft.filter(C.validDraft).length;const count=$('#review-count');if(count)count.textContent=n+' de '+draft.length+' conferidos';const btn=$('#publish-button');if(btn)btn.disabled=!(draft.length&&draft.every(C.validDraft));}
function publishDraft(){if(!draft.length||!draft.every(C.validDraft))return toast('Confira todas as linhas e preencha valores v\u00e1lidos.');const shop=adminShop();let count=0,duplicates=0;for(const d of draft){if(state.products.some(p=>p.storeId===shop.id&&C.norm(p.name)===C.norm(d.name)&&C.norm(p.category)===C.norm(d.category))){duplicates++;continue;}state.products.push({id:C.uid(),storeId:shop.id,name:d.name.trim(),description:d.description.trim(),category:d.category.trim(),price:d.price,available:true,art:'pastel',extras:[]});count++;}save();draft=[];rawText='';draftWarnings=[];importSource='';location.hash='#/cardapio';toast(count+' produto(s) adicionado(s) ao teste.'+(duplicates?' '+duplicates+' duplicado(s) ignorado(s); os existentes n\u00e3o foram alterados.':''));}
function downloadJSON(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),notice:'DEMONSTRACAO: sem dados de producao',...state},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='bocali-dados-de-teste.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function shareShop(id){const s=findShop(id);if(location.protocol==='file:'){openModal('Link direto da loja',`<p class="muted small">Este prot\u00f3tipo ainda n\u00e3o est\u00e1 publicado. Depois da hospedagem, o link abre diretamente a vitrine da loja.</p><label class="field spaced"><span>Rota preparada</span><input readonly value="#/loja/${esc(id)}"></label><div class="notice">N\u00e3o compartilhe o caminho local do arquivo como se fosse um site p\u00fablico.</div>`);return;}const url=location.href.split('#')[0]+'#/loja/'+id;try{await navigator.clipboard.writeText(url);toast('Link copiado. Ele s\u00f3 funciona onde este servidor estiver acess\u00edvel.');}catch{openModal('Link da loja',`<label class="field"><span>${esc(s.name)}</span><input readonly value="${esc(url)}"></label><p class="small muted">O servidor precisa estar acess\u00edvel para quem receber este link.</p>`);}}
/* Local demonstrator: printer dialog requests are never hardware acknowledgements. */
let currentReceipt=null,soundEnabled=false,soundContext=null;
function printerPrefs(){const s=adminShop();return {paper:[58,80].includes(s.printer?.paper)?s.printer.paper:80,autoPrint:s.printer?.autoPrint!==false};}
function myOrder(id){return state.orders.find(o=>o.id===id&&o.storeId===adminShop().id);}
function showAccept(id){
 const o=myOrder(id);if(!o||o.status!=='new')return toast('Pedido j\u00e1 atualizado. Confira a fila.');
 const delivery=o.fulfillment==='delivery',presets=delivery?[[30,45],[45,60],[60,90],[90,120]]:[[10,15],[15,25],[25,35],[35,45]],prefs=printerPrefs();
 openModal('Aceitar '+esc(o.id),`<form id="accept-form" data-id="${esc(o.id)}"><span class="fulfillment-badge ${o.fulfillment}">${delivery?'ENTREGA':'RETIRADA / BALC\u00c3O'}</span><h3 class="accept-question">${delivery?'Em quanto tempo chega ao cliente?':'Em quanto tempo fica pronto para retirar?'}</h3><p class="small muted">${delivery?'Inclua preparo e deslocamento. O cliente ver\u00e1 o prazo total de entrega.':'Informe o tempo de preparo. N\u00e3o h\u00e1 deslocamento de entregador.'} O prazo come\u00e7a no momento do aceite.</p><div class="eta-presets">${presets.map(([min,max],i)=>`<button class="chip ${i===1?'active':''}" type="button" data-action="eta-preset" data-min="${min}" data-max="${max}">${min}\u2013${max} min</button>`).join('')}</div><div class="field-grid"><label class="field"><span>M\u00ednimo (minutos)</span><input id="eta-min" name="min" type="number" min="1" max="240" step="1" required value="${presets[1][0]}"></label><label class="field"><span>M\u00e1ximo (minutos)</span><input id="eta-max" name="max" type="number" min="1" max="240" step="1" required value="${presets[1][1]}"></label></div><div id="eta-preview" class="notice green"></div><label class="check-label spaced"><input id="accept-print" name="print" type="checkbox" ${prefs.autoPrint?'checked':''}>Abrir impress\u00e3o da cozinha ao aceitar</label><p class="small muted" style="margin:10px 0 18px">Papel configurado: ${prefs.paper} mm. Neste teste, voc\u00ea escolhe a impressora e confirma na janela do navegador.</p><button class="btn full" id="confirm-accept" type="submit">${ico('check')} Aceitar com este prazo</button><p class="cart-caption">Pedido e pagamento simulados. Nenhuma mensagem ser\u00e1 enviada.</p></form>`);updateEtaPreview();
}
function updateEtaPreview(){
 const el=$('#eta-preview');if(!el)return;
 const min=Number($('#eta-min').value),max=Number($('#eta-max').value),o=myOrder($('#accept-form').dataset.id);
 if(!Number.isInteger(min)||!Number.isInteger(max)||min<1||max>240||min>max){el.textContent='Informe um intervalo v\u00e1lido de 1 a 240 minutos.';return;}
 const now=Date.now();el.textContent=(o.fulfillment==='delivery'?'Entrega prevista':'Retirada prevista')+': '+clock(now+min*60000)+' a '+clock(now+max*60000)+'. O hor\u00e1rio ser\u00e1 fixado ao aceitar.';
}
function acceptFromForm(form){
 const o=myOrder(form.dataset.id);if(!o)return;const submit=$('#confirm-accept');submit.disabled=true;
 try{const shouldPrint=$('#accept-print').checked;O.accept(o,$('#eta-min').value,$('#eta-max').value);save();closeModal();render();if(shouldPrint)printOrder(o.id,'kitchen');else toast('Pedido aceito com prazo. A comanda ainda precisa ser impressa.');}
 catch(error){toast(error.message);if(submit.isConnected)submit.disabled=false;}
}
function ticketHTML(o,kind,paper,job=null){
 const attempts=O.jobs(o,kind),sequence=job?.sequence||(attempts.length+1),cancel=kind==='cancellation',history=o.status==='completed'||o.status==='dispatched',eta=o.eta,unit=(o.fulfillment==='delivery'?'ENTREGA':'RETIRADA NO BALC\u00c3O');
 return `<section class="kitchen-ticket" style="--ticket-width:${paper}mm"><div class="ticket-test">DEMONSTRA\u00c7\u00c3O \u00b7 N\u00c3O PREPARAR</div><header class="ticket-header"><div class="ticket-brand">bocali.</div><h2>${esc(o.storeName)}</h2><p>${cancel?'AVISO DE CANCELAMENTO':kind==='counter'?'VIA DO BALC\u00c3O':'COMANDA DA COZINHA'}</p><div class="ticket-number">${esc(o.id)}</div><strong class="ticket-mode">${cancel?'CANCELADO \u2014 N\u00c3O PREPARAR':unit}</strong></header>${sequence>1?'<div class="ticket-warning">REIMPRESS\u00c3O '+sequence+'<br>CONFERIR PARA N\u00c3O DUPLICAR O PREPARO</div>':''}${history&&!cancel?'<div class="ticket-warning">HIST\u00d3RICO: '+esc(statusLabel[o.status]).toUpperCase()+'<br>N\u00c3O PREPARAR NOVAMENTE</div>':''}<div class="ticket-meta"><div><b>Cliente:</b> ${esc(o.customerName||'Cliente de teste')}</div><div><b>Pedido:</b> ${dt(o.createdAt)}</div>${o.acceptedAt?'<div><b>Aceite:</b> '+dt(o.acceptedAt)+'</div>':''}<div><b>Via gerada:</b> ${dt(job?.requestedAt||new Date().toISOString())}</div></div>${eta&&!cancel?`<div class="ticket-promise"><span>${o.fulfillment==='delivery'?'ENTREGA PREVISTA':'PRONTO PARA RETIRAR'}</span><strong>${clock(eta.from)} a ${clock(eta.to)}</strong><small>${eta.minMinutes}\u2013${eta.maxMinutes} min desde o aceite \u00b7 ${new Date(eta.to).toLocaleDateString('pt-BR')}</small>${o.fulfillment==='delivery'?'<small>Prazo total ao cliente, n\u00e3o apenas preparo.</small>':''}</div>`:''}<div class="ticket-items">${o.items.map(i=>`<div class="ticket-item"><div class="ticket-item-title"><b>${i.quantity}\u00d7</b><strong>${esc(i.name)}</strong>${kind==='counter'?'<span>'+brl((i.unitPrice+i.extras.reduce((s,e)=>s+e.price,0))*i.quantity)+'</span>':''}</div>${i.extras.length?'<div class="ticket-extras">'+i.extras.map(e=>'+ '+esc(e.name)).join('<br>')+'</div>':''}${i.note?'<div class="ticket-note"><b>OBS. DO ITEM:</b> '+esc(i.note)+'</div>':''}</div>`).join('')}</div>${o.note?'<div class="ticket-note order-wide"><b>OBS. DO PEDIDO:</b><br>'+esc(o.note)+'</div>':''}${kind==='counter'?`<div class="ticket-totals"><div><span>Produtos</span><b>${brl(o.subtotal)}</b></div><div><span>Entrega</span><b>${brl(o.fee)}</b></div><div class="grand"><span>Total simulado</span><b>${brl(o.total)}</b></div><p>${({cash:'Dinheiro',card:'Cart\u00e3o',pix:'Pix'})[o.payment]} \u00b7 N\u00c3O COBRADO</p>${o.fulfillment==='delivery'?(typeof deliveryReceiptHTML==='function'?deliveryReceiptHTML(o):'<p>Endereco de teste nao validado.</p>'):'<p>Retirada simulada no balc\u00e3o.</p>'}</div>`:''}${cancel?'<div class="ticket-warning">INTERROMPER O PREPARO<br>Confirme o cancelamento com a equipe.</div>':''}<footer class="ticket-footer">${o.quantity} unidade(s) \u00b7 Via ${sequence}<br>Documento de teste, n\u00e3o fiscal.<br>Confirme fisicamente se esta via foi impressa.</footer></section>`;
}
function showReceipt(id,kind='kitchen',jobId=null){
 const o=myOrder(id);if(!o||!O.canPrint(o,kind))return toast('Esta comanda n\u00e3o est\u00e1 dispon\u00edvel para o status do pedido.');
 const jobs=O.jobs(o,kind),job=jobs.find(j=>j.id===jobId)||jobs.find(j=>j.status==='requested')||jobs[jobs.length-1]||null,pending=job?.status==='requested',paper=job?.paper||printerPrefs().paper;
 currentReceipt={id,kind,jobId:job?.id||null};
 const history=jobs.length?`<details class="print-log"><summary>Hist\u00f3rico: ${jobs.length} tentativa(s)</summary>${jobs.map(j=>`<p>Via ${j.sequence} \u00b7 ${dt(j.requestedAt)} \u00b7 ${{requested:'aguardando confer\u00eancia',confirmed_by_operator:'operador confirmou sa\u00edda',failed_by_operator:'operador informou que n\u00e3o saiu'}[j.status]}</p>`).join('')}</details>`:'';
 openModal(kind==='cancellation'?'Aviso de cancelamento':'Comanda '+esc(o.id),`<div class="receipt-preview">${ticketHTML(o,kind,paper,job)}</div><div class="receipt-controls">${pending?`<div class="notice">A janela foi solicitada. Ela n\u00e3o comprova que o papel saiu. Confira a impressora antes de confirmar.</div><button class="btn full" data-action="print-result" data-id="${esc(id)}" data-job="${esc(job.id)}" data-success="true">${ico('check')} Confirmei: a comanda saiu</button><button class="btn secondary full" data-action="print-result" data-id="${esc(id)}" data-job="${esc(job.id)}" data-success="false">N\u00e3o saiu / cancelei a impress\u00e3o</button>`:`<div class="notice ${job?.status==='confirmed_by_operator'?'green':''}">${job?.status==='confirmed_by_operator'?'Sa\u00edda confirmada manualmente. Reimprima apenas se necess\u00e1rio.':job?.status==='failed_by_operator'?'A tentativa anterior foi marcada como n\u00e3o impressa. Verifique papel e conex\u00e3o antes de tentar novamente.':'Pr\u00e9via da comanda. Nenhuma impress\u00e3o foi solicitada.'}</div><button class="btn full" data-action="print-order" data-id="${esc(id)}" data-kind="${kind}">${ico('printer')} ${jobs.length?'Reimprimir':'Imprimir'} comanda</button>`}<p class="small muted">Configure ${paper} mm no driver, sem cabe\u00e7alhos e rodap\u00e9s do navegador. A impressora real ainda n\u00e3o foi testada.</p>${history}</div>`);
}
function printOrder(id,kind='kitchen'){
 const o=myOrder(id);if(!o)return;
 try{
  if(O.jobs(o,kind).length&&!confirm('Gerar uma nova via? Confira se a anterior n\u00e3o saiu para evitar duplicar o preparo.'))return;
  const job=O.requestPrint(o,{kind,paper:printerPrefs().paper});save();render();showReceipt(id,kind,job.id);
  let root=$('#print-root');if(!root){root=document.createElement('div');root.id='print-root';document.body.append(root);}
  root.innerHTML=ticketHTML(o,kind,job.paper,job);root.style.width=job.paper+'mm';
  document.body.classList.add('receipt-print-active');
  try{window.print();}catch(err){O.resolvePrint(o,job.id,false);save();render();showReceipt(id,kind,job.id);toast('N\u00e3o foi poss\u00edvel abrir a impress\u00e3o. Use um navegador compat\u00edvel.');}
 }catch(error){toast(error.message);}
}
function confirmPrint(id,jobId,success){const o=myOrder(id);if(!o)return;try{const job=O.resolvePrint(o,jobId,success);save();render();showReceipt(id,job.kind,job.id);toast(success?'Via confirmada pelo operador.':'Tentativa marcada como n\u00e3o impressa.');}catch(error){toast(error.message);}}
function printerHelp(){openModal('Conectar a impressora',`<div class="info-box"><strong>Neste prot\u00f3tipo</strong><p>Use o computador que j\u00e1 imprime no restaurante. Ao aceitar com a op\u00e7\u00e3o de impress\u00e3o ativa, escolha a impressora na janela do navegador. Configure papel de 58 ou 80 mm conforme o equipamento, escala de 100% e desative cabe\u00e7alhos e rodap\u00e9s. Ajuste as margens no driver e confira um teste.</p></div><div class="info-box"><strong>Impress\u00e3o direta, para a vers\u00e3o comercial</strong><p>Depende do modelo da impressora, do tipo de conex\u00e3o e do aparelho usado no balc\u00e3o. Ainda precisamos integrar e testar um conector local ou um recurso oficial do fabricante. Nada foi instalado ou conectado neste pacote.</p></div><div class="info-box"><strong>Confirma\u00e7\u00e3o honesta</strong><p>Solicitar uma impress\u00e3o n\u00e3o significa que o papel saiu. Falta de papel, driver ou cancelamento devem ser conferidos pelo operador. N\u00e3o reimprima sem verificar a via anterior.</p></div><div class="notice spaced">Confira sempre o papel antes de solicitar uma segunda via.</div>`);}
function createDemoOrder(mode){
 const s=adminShop(),p=state.products.find(p=>p.storeId===s.id&&p.available);if(!p)return toast('Cadastre um produto dispon\u00edvel para testar.');
 const originalCart=state.cart;let order;
 try{const quantity=Math.max(2,Math.ceil(s.minimum/p.price));state.cart={storeId:s.id,items:[{id:C.uid(),productId:p.id,name:p.name,unitPrice:p.price,quantity,extras:p.extras?.length?[{...p.extras[0]}]:[],note:'Sem azeitona. Observa\u00e7\u00e3o de teste.'}]};order=C.createOrder(state,{fulfillment:mode,delivery:mode==='delivery'&&window.PedeDelivery?window.PedeDelivery.confirmSelection(s,window.PedeDelivery.sample(0)):null,payment:'cash',note:'Embalar separadamente. Pedido fict\u00edcio: n\u00e3o preparar.'});}
 catch(error){toast(error.message);}finally{state.cart=originalCart;}
 if(order){orderFilter='all';save();render();beep();toast('Pedido '+order.id+' criado na fila. Nenhum pedido real foi enviado.');}
}
function beep(){if(!soundEnabled||view!=='painel'||document.hidden||!soundContext)return;try{const now=soundContext.currentTime,osc=soundContext.createOscillator(),gain=soundContext.createGain();osc.type='sine';osc.frequency.value=740;gain.gain.setValueAtTime(0.001,now);gain.gain.exponentialRampToValueAtTime(0.15,now+0.03);gain.gain.exponentialRampToValueAtTime(0.001,now+0.45);osc.connect(gain);gain.connect(soundContext.destination);osc.start(now);osc.stop(now+0.5);}catch{}}
async function toggleSound(){if(soundEnabled){soundEnabled=false;render();return;}try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw new Error();soundContext=soundContext||new AC();await soundContext.resume();soundEnabled=true;beep();render();toast('Som ativo enquanto o painel estiver aberto nesta aba.');}catch{toast('N\u00e3o foi poss\u00edvel ativar o som neste navegador.');}}
setInterval(()=>{if(soundEnabled&&state.orders.some(o=>o.storeId===adminShop().id&&o.status==='new'))beep();},15000);

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;switch(a){
case'accept-order':showAccept(id);break;
case'eta-preset':$('#eta-min').value=b.dataset.min;$('#eta-max').value=b.dataset.max;$$('.eta-presets .chip').forEach(el=>el.classList.toggle('active',el===b));updateEtaPreview();break;
case'receipt':showReceipt(id,b.dataset.kind);break;
case'print-order':printOrder(id,b.dataset.kind);break;
case'print-result':confirmPrint(id,b.dataset.job,b.dataset.success==='true');break;
case'printer-help':printerHelp();break;
case'demo-order':createDemoOrder(b.dataset.mode);break;
case'toggle-sound':toggleSound();break;
case'favorite':state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();break;
case'category':filter=b.dataset.category;render();break;
case'product':showProduct(id);break;
case'close-modal':closeModal();break;
case'product-minus':modalQty=Math.max(1,modalQty-1);productTotal();break;
case'product-plus':modalQty=Math.min(20,modalQty+1);productTotal();break;
case'add-cart':addToCart();break;
case'cart':cartModal();break;
case'cart-minus':case'cart-plus':{const i=state.cart.items[+b.dataset.index];if(!i)break;i.quantity+=a==='cart-plus'?1:-1;i.quantity=Math.min(20,i.quantity);state.cart.items=state.cart.items.filter(x=>x.quantity>0);if(!state.cart.items.length)state.cart.storeId=null;save();const wasModal=$('#modal').open;render();if(wasModal)cartModal();break;}
case'checkout':checkout();break;
case'place-order':placeOrder();break;
case'goto-orders':closeModal();location.hash='#/pedidos';break;
case'goto-admin':state.adminStore=b.dataset.store;save();closeModal();location.hash='#/painel';break;
case'reorder':reorder(id);break;
case'toggle-store':adminShop().open=!adminShop().open;save();render();break;
case'order-filter':orderFilter=b.dataset.filter;render();break;
case'status':{const o=state.orders.find(o=>o.id===id&&o.storeId===adminShop().id);if(!o)break;if(b.dataset.to==='cancelled'&&!confirm('Cancelar este pedido de teste? Nenhum valor real ser\u00e1 estornado, pois n\u00e3o houve cobran\u00e7a.'))break;try{C.transition(o,b.dataset.to);save();render();toast(o.status==='cancelled'&&o.acceptedAt?'Pedido cancelado. Avise a cozinha e use o aviso de cancelamento.':'Pedido atualizado: '+statusLabel[o.status]+'.');}catch(err){toast(err.message);}break;}
case'toggle-product':{const p=state.products.find(p=>p.id===id&&p.storeId===adminShop().id);if(p){p.available=!p.available;save();render();}break;}
case'edit-product':editProduct(id);break;
case'new-product':editProduct();break;
case'parse-text':importSource='Texto colado manualmente.';parseText();break;
case'sample-menu':rawText='ESPECIAIS\nPastel de palmito R$ 18,90\nPastel de calabresa R$ 17,50\nBEBIDAS\nSuco de uva 300 ml R$ 8,00\nDOCES\nChocolate P R$ 12,00 G R$ 18,00';$('#raw-text').value=rawText;toast('Exemplo inserido. Toque em Organizar produtos.');break;
case'add-draft':draft.push({id:C.uid(),name:'',description:'',category:'Importados',price:null,source:'Cadastro manual',reviewed:false});render();break;
case'review-clear':{let n=0;for(const d of draft){if(d.confidence==='high'&&!d.ambiguous&&Number.isInteger(d.price)&&d.price>0&&d.name.trim()&&d.category.trim()){if(!d.reviewed)n++;d.reviewed=true;}}render();toast(n?n+' item(ns) de leitura clara marcados. Ainda confira o PDF antes de publicar.':'Nenhum item novo de leitura clara para marcar.');break;}
case'remove-draft':draft=draft.filter(d=>d.id!==id);render();break;
case'publish':publishDraft();break;
case'export':downloadJSON();break;
case'reset':if(confirm('Apagar favoritos, pedidos, produtos editados e sacola deste teste? Os dados originais de exemplo ser\u00e3o restaurados.')){state=C.seed();draft=[];rawText='';save();location.hash='#/minhas-lojas';render();toast('Demonstra\u00e7\u00e3o reiniciada.');}break;
case'share':shareShop(id);break;
}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='eta-min'||t.id==='eta-max'){updateEtaPreview();$$('.eta-presets .chip').forEach(el=>el.classList.remove('active'));}else if(t.id==='menu-search'){search=t.value;const products=state.products.filter(p=>p.storeId===shopId&&p.available&&(filter==='Todos'||p.category===filter)&&C.norm(p.name+' '+p.description).includes(C.norm(search)));$('#product-results').innerHTML=products.map(productCard).join('')||'<p class="muted">Nenhum produto encontrado.</p>';}else if(t.id==='store-search'){search=t.value;$('#explore-results').innerHTML=state.stores.filter(s=>C.norm(s.name+' '+s.type).includes(C.norm(search))).map(storeCard).join('')||'<p class="muted">Nenhuma loja encontrada.</p>';}else if(t.id==='raw-text')rawText=t.value;else if(t.dataset.draftId){const d=draft.find(d=>d.id===t.dataset.draftId);if(!d)return;d[t.dataset.field]=t.dataset.field==='price'?C.moneyToCents(t.value):t.value;d.reviewed=false;const cb=$(`[data-review="${d.id}"]`);if(cb)cb.checked=false;updateDraftProgress();}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='printer-width'||t.id==='auto-print'){adminShop().printer={paper:Number($('#printer-width').value),autoPrint:$('#auto-print').checked};save();}else if(t.id==='admin-select'){if(importBusy){t.value=state.adminStore;toast('Aguarde a leitura do PDF antes de trocar de loja.');return;}if(draft.length&&!confirm('Trocar de loja descarta o rascunho n\u00e3o publicado. Continuar?')){t.value=state.adminStore;return;}state.adminStore=t.value;draft=[];rawText='';orderFilter='all';save();render();}else if(t.dataset.extra){modalExtras=t.checked?[...modalExtras,t.dataset.extra]:modalExtras.filter(x=>x!==t.dataset.extra);productTotal();}else if(t.name==='fulfillment'){checkoutMode=t.value;$('#checkout-totals').innerHTML=checkoutTotals();$('#delivery-example').style.display=t.value==='delivery'?'block':'none';}else if(t.name==='payment')checkoutPayment=t.value;else if(t.id==='pdf-file')importPdf(t.files[0]);else if(t.dataset.review){const d=draft.find(d=>d.id===t.dataset.review);if(d){d.reviewed=t.checked;updateDraftProgress();}}});
document.addEventListener('submit',e=>{if(e.target.id==='accept-form'){e.preventDefault();acceptFromForm(e.target);return;}if(e.target.id!=='product-form')return;e.preventDefault();const f=e.target,data=new FormData(f),price=C.moneyToCents(data.get('price'));if(price===null)return toast('Informe um pre\u00e7o v\u00e1lido, maior que zero.');const name=String(data.get('name')).trim(),category=String(data.get('category')).trim();if(!name||!category)return toast('Preencha nome e categoria.');const values={name,category,price,description:String(data.get('description')).trim(),art:String(data.get('art'))};if(f.dataset.id){const p=state.products.find(p=>p.id===f.dataset.id&&p.storeId===adminShop().id);if(!p)return;Object.assign(p,values);}else state.products.push({id:C.uid(),storeId:adminShop().id,...values,available:true,extras:[]});save();closeModal();render();toast('Produto salvo no teste.');});
window.addEventListener('afterprint',()=>{document.body.classList.remove('receipt-print-active');$('#print-root')?.replaceChildren();});
window.addEventListener('hashchange',route);
window.addEventListener('storage',e=>{if(e.key===KEY){state=load();if(!$('#modal').open)render();}});
route();save();
